90	def numeric_summary_function() -> str:
91	    return r"""
92	function [value_count, finite_count, sum_squares] = task025_numeric_summary(value)
93	value_count = 0;
94	finite_count = 0;
95	sum_squares = 0;
96	if isnumeric(value) || islogical(value)
97	    flat = value(:);
98	    finite_mask = isfinite(real(flat)) & isfinite(imag(flat));
99	    value_count = numel(flat);
100	    finite_count = sum(finite_mask);
101	    if finite_count == value_count
102	        sum_squares = sum(abs(flat) .^ 2);
103	    else
104	        sum_squares = NaN;
105	    end
106	elseif iscell(value)
107	    for item_idx = 1:numel(value)
108	        [child_count, child_finite, child_sum] = task025_numeric_summary(value{item_idx});
109	        value_count = value_count + child_count;
110	        finite_count = finite_count + child_finite;
111	        sum_squares = sum_squares + child_sum;
112	    end
113	elseif isstruct(value)
114	    for item_idx = 1:numel(value)
115	        names = fieldnames(value(item_idx));
116	        for field_idx = 1:numel(names)
117	            child = value(item_idx).(names{field_idx});
118	            [child_count, child_finite, child_sum] = task025_numeric_summary(child);
119	            value_count = value_count + child_count;
120	            finite_count = finite_count + child_finite;
121	            sum_squares = sum_squares + child_sum;
122	        end
123	    end
124	end
125	end
126	"""
