364	def run_octave(
365	    octave: str,
366	    generated_dir: Path,
367	    source_paths: list[Path],
368	    expression: str,
369	) -> str:
370	    setup = "".join(
371	        "addpath('%s', '-end');" % octave_quote(str(path)) for path in source_paths
372	    )
373	    setup += "addpath('%s', '-begin');" % octave_quote(str(generated_dir))
374	    completed = subprocess.run(
375	        [octave, "--no-gui", "--quiet", "--eval", setup + expression],
376	        cwd=generated_dir,
377	        text=True,
378	        stdout=subprocess.PIPE,
379	        stderr=subprocess.STDOUT,
380	        check=False,
381	        timeout=240,
382	    )
383	    if completed.returncode != 0:
384	        raise RuntimeError(
385	            "Octave workflow failed with exit code %s:\n%s"
386	            % (completed.returncode, completed.stdout)
387	        )
388	    return completed.stdout
