391	def parse_observations(paths: list[Path]) -> dict[str, dict[str, object]]:
392	    observed: dict[str, dict[str, object]] = {
393	        "edited_model": {},
394	        "quantitative_report": {},
395	    }
396	    for path in paths:
397	        if not path.is_file():
398	            raise RuntimeError(f"workflow did not produce {path.name}")
399	        for line in path.read_text(encoding="utf-8").splitlines():
400	            fields = line.split("\t")
401	            kind = fields[0]
402	            if kind == "edited_model" and len(fields) == 7:
403	                record_id = fields[1]
404	                result = {
405	                    "sequence": fields[2],
406	                    "completed": fields[3] == "1",
407	                    "numeric_value_count": int(fields[4]),
408	                    "finite_value_count": int(fields[5]),
409	                    "numeric_l2_norm": float(fields[6]),
410	                }
411	            elif kind == "quantitative_report" and len(fields) == 6:
412	                record_id = fields[1]
413	                result = {
414	                    "completed": fields[2] == "1",
415	                    "numeric_value_count": int(fields[3]),
416	                    "finite_value_count": int(fields[4]),
417	                    "numeric_l2_norm": float(fields[5]),
418	                }
419	            else:
420	                raise RuntimeError(f"malformed workflow output: {line!r}")
421	            panel = observed[kind]
422	            if record_id in panel:
423	                raise RuntimeError(f"duplicate workflow record: {kind}/{record_id}")
424	            panel[record_id] = result
425	    return observed
