428	def panel_report(
429	    records: list[dict[str, object]], observed: dict[str, dict[str, object]]
430	) -> dict[str, object]:
431	    expected_ids = {str(record["record_id"]) for record in records}
432	    if set(observed) != expected_ids:
433	        missing = sorted(expected_ids - set(observed))
434	        extra = sorted(set(observed) - expected_ids)
435	        raise RuntimeError(
436	            f"workflow record mismatch: missing={missing}, extra={extra}"
437	        )
438	
439	    rows: list[dict[str, object]] = []
440	    for record in records:
441	        record_id = str(record["record_id"])
442	        result = observed[record_id]
443	        value_count = int(result["numeric_value_count"])
444	        finite_count = int(result["finite_value_count"])
445	        l2_norm = float(result["numeric_l2_norm"])
446	        if not bool(result["completed"]):
447	            raise RuntimeError(f"workflow did not complete: {record_id}")
448	        if value_count <= 0 or finite_count != value_count:
449	            raise RuntimeError(
450	                f"workflow produced incomplete numeric observations: {record_id}"
451	            )
452	        if not math.isfinite(l2_norm):
453	            raise RuntimeError(
454	                f"workflow produced a non-finite numeric summary: {record_id}"
455	            )
456	        rows.append(
457	            {
458	                "record_id": record_id,
459	                **result,
460	                "workflow_completed": True,
461	            }
462	        )
463	    return {"records": rows, "workflow_completed": True}
