77	% detCrArea.m
78	% Georg Oeltzschner, Johns Hopkins University 2020
79	% 
80	% USAGE:
81	% [CrArea] = detCrArea(buffer);
82	% 
83	% DESCRIPTION:
84	% Finds the creatine spectrum in the temporary basis set buffer, then fits
85	% a Lorentzian to the 3.027 ppm CH3 creatine singlet to determine its area.
86	% Subsequently, macromolecule and lipid basis functions are scaled
87	% accordingly.
88	% 
89	% INPUTS:
90	% in        = a temporary buffer containing simulated basis functions
91	%
92	% OUTPUTS:
93	% CrArea    = Estimated area under the 3.027 ppm CH3 Cr singlet.
94	
95	
96	function [CrArea] = detCrArea(in);
97	
98	% Find the creatine basis function
99	idx_Cr          = find(strcmp(in.name,'Cr'));
100	if isempty(idx_Cr)
101	    error('No basis function with nametag ''Cr'' found! Abort!');
102	end
103	
104	%[~, idx_3027]   = min(abs(buffer.ppm(:,1)-3.027));
105	
106	% Determine the window where we are going to look for the peak.
107	ppm = in.ppm(1,:);
108	ppmmin = 3.027 - 0.4;
109	ppmmax = 3.027 + 0.4;
110	refWindow = in.specs(ppm>ppmmin & ppm<ppmmax, idx_Cr);
111	ppmWindow = in.ppm(ppm>ppmmin & ppm<ppmmax);
112	
113	% Find the maximum and its index
114	maxRef_index    = find(abs(real(refWindow)) == max(abs(real((refWindow)))));
115	maxRef          = real(refWindow(maxRef_index));
116	
117	% Determine an initial estimate for the FWHM
118	% Peak lines can be super narrow, so overestimate it slightly
119	gtHalfMax   = find(abs(real(refWindow)) >= 0.4*abs(maxRef));
120	FWHM1       = abs(ppmWindow(gtHalfMax(1)) - ppmWindow(gtHalfMax(end)));
121	FWHM1       = FWHM1*(42.577*in.Bo(1));  %Assumes proton.
122	
123	% Determine an initial estimate for the center frequency of the Cr peak
124	crFreq = ppmWindow(maxRef_index);
125	
126	% Set up the fit
127	parsGuess=zeros(1,5);
128	parsGuess(1) = maxRef;  % amplitude
129	parsGuess(2) = (5*in.Bo/3)/(42.577*in.Bo); %FWHM.  Assumes Proton.  LW = 5/3 Hz/T.   % FWHM. Assumes Proton.
130	parsGuess(3) = crFreq;  % center frequency
131	parsGuess(4) = 0;       % baseline offset
132	parsGuess(5) = 0;       % phase
133	    
134	% Run first guess
135	yGuess  = op_lorentz(parsGuess, ppmWindow);
136	parsFit = nlinfit(ppmWindow, real(refWindow'), @op_lorentz, parsGuess);
