1	% op_gaussianPeak.m
2	% Jamie Near, McGill University 2014.
3	% 
4	% USAGE:
5	% out=op_gaussianPeak(n,sw,Bo,centerFreq,lw,ppm0,amp);
6	% 
7	% DESCRIPTION:
8	% Generate a noiseless spectrum containing a single gaussian peak with
9	% desired parameters (frequency, amplitude, linewidth, etc.).
10	% 
11	% INPUTS:
12	% n             = Number of points in spectrum.
13	% sw            = spectral width of spectrum (Hz).
14	% Bo            = Magnetic field strength (Tesla).
15	% centerFreq    = center frequency of the spectrum (ppm).
16	% lw            = Linewidth of gaussian peak (Hz).
17	% ppm0          = Frequency of gaussian peak (ppm).
18	% amp           = Amplitude of gaussian peak.  
19	%
20	% OUTPUTS:
21	% out    = Gaussian lineshape peak in FID-A structure format 
22	
23	
24	function out=op_gaussianPeak(n,sw,Bo,centerFreq,lw,ppm0,amp);
25	
26	dt=1/sw;
27	df=sw/n;
28	decay=1/(lw*pi);
29	f0=(-centerFreq+ppm0)*(Bo*42.577)* 2 * pi;
30	
31	t=[0:dt:(n-1)*dt];
32	f=[(-sw/2+(df/2)):df:(sw/2-(df/2))];
33	
34	ppm=f/(Bo*42.577);
35	ppm=ppm+4.68;
36	ppm=ppm-(4.68-centerFreq);
37	
38	fids=amp * exp(-(t.^2)/(2*(decay^2))) .* exp(-1j*f0*t);
39	fids=fids';
40	
41	specs=fftshift(fft(fids,[],1),1);
42	
43	out.t=t;
44	out.fids=fids;
45	out.ppm=ppm;
46	out.specs=specs;
47	
48	%FILLING IN DATA STRUCTURE
49	
50	out.sz=size(out.fids);
51	out.spectralwidth=sw;
52	out.dwelltime=dt;
53	out.txfrq=Bo*42.577;
54	out.centerFreq=centerFreq;
55	out.date=date;
56	out.dims.t=1;
57	out.dims.averages=0;
58	out.dims.subSpecs=0;
59	out.dims.coils=0;
60	out.Bo=Bo;
61	out.averages=1;
62	out.rawAverages=1;
63	out.subspecs=1;
64	out.rawSubspecs=1;
65	
66	%FILLING IN THE FLAGS
67	out.flags.writtentostruct=1;
68	out.flags.gotparams=1;
69	out.flags.leftshifted=0;
70	out.flags.filtered=0;
71	out.flags.zeropadded=0;
72	out.flags.freqcorrected=0;
73	out.flags.phasecorrected=0;
74	out.flags.averaged=0;
75	out.flags.addedrcvrs=0;
76	out.flags.subtracted=0;
77	out.flags.writtentotext=0;
78	out.flags.downsampled=0;
79	if out.dims.subSpecs==0
80	    out.flags.isFourSteps=0;
81	else
82	    out.flags.isFourSteps=(out.sz(out.dims.subSpecs)==4);
83	end

1	% op_dccorr.m
2	% Jamie Near, McGill University 2014.
3	% 
4	% USAGE:
5	% [out,dcOffset]=op_dccorr(in,mode,var1);
6	% 
7	% DESCRIPTION:
8	% Do a DC Correction on the data.  This method is a frequency domain
9	% operation.
10	% 
11	% INPUTS:
12	% in	= input data in matlab structure format.  
13	% mode	= ppmrange('p') or Value('v').  In ppmrange mode, the DC offset is
14	%           calculated automatically over a defined ppm range in the 
15	%           spectrum.  In value mode, the user has to provide the value of 
16	%           the desired DC offset.
17	% var1	= If mode is 'p', then 'var1' is the range of ppm values 
18	%           [minppm maxppm] over which to calculate the DC offset.  In 
19	%           ppmrange mode, the 'var1' is optional, and takes a default 
20	%           value of [max(in.ppm)-0.5 max(in.ppm] AND 
21	%           [min(in.ppm) min(in.ppm)+0.5].  If mode is 'v', then 'var1' is 
22	%           the value of the dc offset correction that you wish to employ.
23	%
24	% OUTPUTS:
25	% out   = Output following DC correction.  
26	
27	function [out,dcOffset]=op_dccorr(in,mode,var1);
28	
29	if mode=='p'
30	    if nargin<3
31	        var1a=[max(in.ppm)-0.5 max(in.ppm)];
32	        var1b=[min(in.ppm) min(in.ppm)+0.5];
33	        dcOffset1=mean(in.specs(in.ppm<var1a(2) & in.ppm>var1a(1)));
34	        dcOffset2=mean(in.specs(in.ppm<var1b(2) & in.ppm>var1b(1)));
35	        dcOffset=mean([dcOffset1 dcOffset2]);
36	    else
37	        dcOffset=mean(in.specs(in.ppm<var1(2) & in.ppm>var1(1)));
38	    end
39	elseif mode=='v'
40	    dcOffset=var1;
41	end
42	
43	specs=in.specs-dcOffset;
44	
45	%convert back to time domain
46	%if the length of Fids is odd, then you have to do a circshift of one to
47	%make sure that you don't introduce a small frequency shift into the fids
48	%vector.
49	if mod(size(specs,in.dims.t),2)==0
50	    %disp('Length of vector is even.  Doing normal conversion');
51	    fids=ifft(fftshift(specs,in.dims.t),[],in.dims.t);
52	else
53	    %disp('Length of vector is odd.  Doing circshift by 1');
54	    fids=ifft(circshift(fftshift(specs,in.dims.t),1),[],in.dims.t);
55	end
56	
57	%FILLING IN DATA STRUCTURE
58	out=in;
59	out.fids=fids;
60	out.specs=specs;
61	
62	%FILLING IN THE FLAGS
63	out.flags=in.flags;
64	out.flags.writtentostruct=1;
65	out.flags.freqranged=1;

320	        end
