function diag_study(matfile)
records = {matfile};
checkpoint = load(matfile);
sequence = task025_text(checkpoint.sequence);
basis = struct();
basis.t = checkpoint.time;
basis.fids = checkpoint.fids;
basis.ppm = checkpoint.ppm;
basis.specs = checkpoint.specs;
basis.sz = size(basis.fids);
basis.spectralwidth = double(checkpoint.spectral_width(1));
basis.dwelltime = 1 / basis.spectralwidth;
basis.txfrq = double(checkpoint.field_strength(1)) * 42.577;
basis.centerFreq = double(checkpoint.center_ppm(1));
basis.date = 'offline-checkpoint';
basis.dims = struct('t', 1, 'averages', 0, 'subSpecs', 0, 'coils', 0);
basis.Bo = double(checkpoint.field_strength(1));
basis.averages = 1;
basis.rawAverages = 1;
basis.subspecs = 1;
basis.rawSubspecs = 1;
basis.flags = struct('writtentostruct',1,'gotparams',1,'leftshifted',0,'filtered',0,'zeropadded',0,'freqcorrected',0,'phasecorrected',0,'averaged',0,'addedrcvrs',0,'subtracted',0,'writtentotext',0,'downsampled',0,'isFourSteps',0);
basis.n = double(checkpoint.points(1));
basis.name = task025_strings(checkpoint.component_names);
basis.names = task025_strings(checkpoint.subspectrum_names);
basis.nMets = double(checkpoint.n_metabolites(1));
basis.nMM = double(checkpoint.n_macromolecules(1));

container = struct();
container.outputFolder = pwd;
container.outputFile = 'diag_ignored.mat';
container.nDatasets = 1;
container.flags = struct();
container.flags.isGUI = 0;
container.flags.isPRIAM = 0;
container.flags.isMRSI = 0;
container.flags.isUnEdited = strcmp(sequence, 'unedited');
container.flags.isMEGA = strcmp(sequence, 'MEGA');
container.flags.isHERMES = strcmp(sequence, 'HERMES');
container.flags.isHERCULES = strcmp(sequence, 'HERCULES');
container.flags.hasRef = 0;
container.flags.hasWater = 0;
container.flags.didFit = 0;
container.flags.speedUp = 0;
container.flags.hasMM = 0;
container.ver = struct('Osp', 'checkpoint', 'CheckOsp', 'checkpoint');
container.runtime = struct();
container.opts = struct();
container.opts.savePDF = 0;
container.opts.fit = struct('method', 'Osprey', 'style', 'Separate', 'coMM3', task025_text(checkpoint.model_option), 'FWHMcoMM3', 14, 'MeanMM', 0);
container.opts.fit.GAP = struct('A', 0, 'sum', 0, 'diff1', 0, 'diff2', 0);
container.info.metab.unique_ndatapoint_spectralwidth_ind = 1;
container.info.metab.unique_ndatapoint_spectralwidth = {'spec_1'};
container.fit.basisSet = basis;
container.fit.scale = {1};
container.processed.metab = {struct('sequence', sequence)};

fprintf('=== %s (%s) ===\n', matfile, sequence);

% Diagnose detCrArea inputs for this sequence
if container.flags.isMEGA
    ref_b = basis; ref_b.fids = basis.fids(:,:,1); ref_b.specs = basis.specs(:,:,1);
    d1_b  = basis; d1_b.fids  = basis.fids(:,:,3); d1_b.specs  = basis.specs(:,:,3);
else
    ref_b = basis; ref_b.fids = basis.fids(:,:,7); ref_b.specs = basis.specs(:,:,7);
    d1_b  = basis; d1_b.fids  = basis.fids(:,:,5); d1_b.specs  = basis.specs(:,:,5);
end
[CrArea] = diag_detCrArea(ref_b);
fprintf('reference CrArea = %.10g\n', CrArea);
oneProtonArea = CrArea/3;
hzppm = basis.Bo*42.577;
n = basis.n; sw = basis.spectralwidth; Bo = basis.Bo; cf = basis.centerFreq;
testGaussian = op_gaussianPeak(n, sw, Bo, cf, 0.1*hzppm, 0, 1);
testGaussian = op_dccorr(testGaussian, 'p');
gaussianArea = sum(real(testGaussian.specs));
fprintf('gaussianArea = %.10g\n', gaussianArea);
fprintf('MM3co amplitude param = 2*oneProtonArea/gaussianArea = %.10g\n', 2*oneProtonArea/gaussianArea);
MM3co = op_gaussianPeak(n, sw, Bo, cf, 14, 3, 2*oneProtonArea/gaussianArea);
MM3co = op_dccorr(MM3co, 'p');
fprintf('MM3co L2 (fids+specs) = %.10g\n', sqrt(sum(abs(MM3co.fids(:)).^2) + sum(abs(MM3co.specs(:)).^2)));

result = OspreyFit(container);
fn = fieldnames(result.fit.resBasisSet);
for i = 1:numel(fn)
    grp = result.fit.resBasisSet.(fn{i});
    sub = fieldnames(grp);
    for j = 1:numel(sub)
        cells = grp.(sub{j});
        for c = 1:numel(cells)
            b = cells{c};
            if isempty(b), continue, end
            ss_fids = sum(abs(b.fids(:)).^2);
            ss_specs = sum(abs(b.specs(:)).^2);
            fprintf('cell {%s}.%s{%d}: sum|fids|^2=%.10g sum|specs|^2=%.10g\n', fn{i}, sub{j}, c, ss_fids, ss_specs);
            % per-component L2
            fprintf('  per-comp fids L2: '); fprintf('%.6g ', sqrt(sum(abs(b.fids).^2,1)));
            fprintf('\n  per-comp specs L2: '); fprintf('%.6g ', sqrt(sum(abs(b.specs).^2,1)));
            fprintf('\n');
        end
    end
end
end

function values = task025_strings(value)
if iscell(value)
    values = value;
else
    values = cellstr(value);
end
values = values(:)';
for idx = 1:numel(values)
    values{idx} = task025_text(values{idx});
end
end

function value = task025_text(raw)
if iscell(raw)
    raw = raw{1};
end
value = strtrim(char(raw));
end

% direct copy of detCrArea from osp_addDiffMMPeaks.m
function [CrArea] = diag_detCrArea(in);
idx_Cr = find(strcmp(in.name,'Cr'));
if isempty(idx_Cr)
    error('No basis function with nametag ''Cr'' found! Abort!');
end
ppm = in.ppm(1,:);
ppmmin = 3.027 - 0.4;
ppmmax = 3.027 + 0.4;
refWindow = in.specs(ppm>ppmmin & ppm<ppmmax, idx_Cr);
ppmWindow = in.ppm(ppm>ppmmin & ppm<ppmmax);
maxRef_index = find(abs(real(refWindow)) == max(abs(real((refWindow)))));
maxRef = real(refWindow(maxRef_index));
gtHalfMax = find(abs(real(refWindow)) >= 0.4*abs(maxRef));
FWHM1 = abs(ppmWindow(gtHalfMax(1)) - ppmWindow(gtHalfMax(end)));
FWHM1 = FWHM1*(42.577*in.Bo(1));
crFreq = ppmWindow(maxRef_index);
parsGuess=zeros(1,5);
parsGuess(1) = maxRef;
parsGuess(2) = (5*in.Bo/3)/(42.577*in.Bo);
parsGuess(3) = crFreq;
parsGuess(4) = 0;
parsGuess(5) = 0;
yGuess = op_lorentz(parsGuess, ppmWindow);
parsFit = nlinfit(ppmWindow, real(refWindow'), @op_lorentz, parsGuess);
yFit = op_lorentz(parsFit, ppmWindow);
fprintf('  detCrArea internals: maxRef=%.10g crFreq=%.10g FWHM1=%.10g\n', maxRef, crFreq, FWHM1);
CrArea = sum(yFit);
end

